<template>
	<EdgeAppShell product="vetedge" title="Veterinary" :tenant-name="identity.tenant_name || ''" :branch-name="branchName" :user-name="userName" :active-route="activeRoute" @navigate="openRoute">
		<EdgePageLayout>
			<template #header><EdgePageHeader eyebrow="Front Desk Operations" :title="pageTitle" :subtitle="pageSubtitle" action-label="Refresh" @action="refreshAll" /></template>
			<section class="frontdesk-summary"><EdgeStatCard label="Guest requests" :value="summary.guest_requests || 0" icon="clipboard" /><EdgeStatCard label="Today's appointments" :value="summary.today_appointments || 0" icon="calendar" /><EdgeStatCard label="Open missed" :value="summary.open_missed || 0" icon="activity" /></section>
			<nav v-if="!fixedTab" class="frontdesk-tabs" aria-label="Front desk workflows"><button v-for="option in tabOptions" :key="option.value" type="button" :class="['frontdesk-tab', { 'is-active': tab === option.value }]" @click="changeTab(option.value)"><span>{{ option.label }}</span><small>{{ option.description }}</small></button></nav>
			<template #filters>
				<EdgeFilterBar title="Filter front desk work">
					<div class="frontdesk-filters">
						<EdgeLinkField :model-value="filters.branch || ''" label="Branch" placeholder="All permitted branches" :searcher="(query) => linkSearch('branch', query)" @update:model-value="(value) => setFilter('branch', value)" />
						<EdgeLinkField v-if="tab === 'queue'" :model-value="filters.practitioner || ''" label="Practitioner" placeholder="All doctors" :searcher="(query) => linkSearch('practitioner', query)" @update:model-value="(value) => setFilter('practitioner', value)" />
						<EdgeDropdown v-if="tab === 'queue'" :model-value="filters.status || ''" label="Status" placeholder="Active queue statuses" :options="appointmentStatusOptions" @update:model-value="(value) => setFilter('status', value)" />
						<EdgeDropdown v-if="tab === 'guest'" :model-value="filters.status || ''" label="Status" placeholder="All statuses" :options="guestStatusOptions" @update:model-value="(value) => setFilter('status', value)" />
						<EdgeDropdown v-if="tab === 'missed'" :model-value="filters.status || ''" label="Status" placeholder="All statuses" :options="missedStatusOptions" @update:model-value="(value) => setFilter('status', value)" />
						<EdgeDropdown v-if="tab === 'missed'" :model-value="filters.resolved || ''" label="Resolution" placeholder="All" :options="resolutionOptions" @update:model-value="(value) => setFilter('resolved', value)" />
						<EdgeInput v-if="tab !== 'queue'" v-model="filters.search" type="search" label="Search" placeholder="Name, patient, owner or phone" @keyup.enter="applyFilters" />
					</div>
					<template #actions><button type="button" class="edge-button edge-button--primary" :disabled="loading" @click="applyFilters">Apply</button><button type="button" class="edge-button" :disabled="loading" @click="resetFilters">Reset</button></template>
				</EdgeFilterBar>
			</template>

			<EdgeLoadingState v-if="loading" :message="`Loading ${pageTitle}...`" :skeleton="true" />
			<EdgeErrorState v-else-if="error" :title="`${pageTitle} could not load`" :message="error" action-label="Try again" @retry="refreshAll" />
			<template v-else-if="tab === 'queue'">
				<section v-for="section in queueSections" :key="section.key" class="frontdesk-section"><header><div><h3>{{ section.label }}</h3><p>{{ section.description }}</p></div><strong>{{ section.rows.length }}</strong></header><EdgeDataTable :columns="queueColumns" :rows="section.rows" :actions="openAction" empty-title="No appointments" empty-description="No appointments match this time bucket and filter." @row-click="openQueueDetail" @action="({ row }) => openQueueDetail(row)" /></section>
			</template>
			<template v-else-if="tab === 'guest'">
				<EdgeDataTable :columns="guestColumns" :rows="guestList.rows || []" :actions="openAction" empty-title="No guest booking requests" empty-description="No booking requests match the current filters." @row-click="openGuestDetail" @action="({ row }) => openGuestDetail(row)"><template #footer><span>Showing {{ guestFirstVisible }}–{{ guestLastVisible }} of {{ guestList.total || 0 }}</span><div class="frontdesk-actions"><button type="button" class="edge-button edge-button--compact" :disabled="!guestHasPrevious" @click="previousGuestPage">Previous</button><button type="button" class="edge-button edge-button--compact" :disabled="!guestHasNext" @click="nextGuestPage">Next</button></div></template></EdgeDataTable>
			</template>
			<template v-else>
				<section class="frontdesk-notice"><strong>Conflict-safe actions</strong><p>Actions use the latest server timestamp. Concurrent changes must be refreshed rather than overwritten.</p></section>
				<EdgeDataTable :columns="missedColumns" :rows="missedList.rows || []" :actions="openAction" empty-title="No missed appointments" empty-description="No missed appointments match the current filters." @row-click="openMissedDetail" @action="({ row }) => openMissedDetail(row)"><template #footer><span>Showing {{ missedFirstVisible }}–{{ missedLastVisible }} of {{ missedList.total || 0 }}</span><div class="frontdesk-actions"><button type="button" class="edge-button edge-button--compact" :disabled="!missedHasPrevious" @click="previousMissedPage">Previous</button><button type="button" class="edge-button edge-button--compact" :disabled="!missedHasNext" @click="nextMissedPage">Next</button></div></template></EdgeDataTable>
			</template>
		</EdgePageLayout>

		<EdgeModal :open="detail.open" :title="detailTitle" :subtitle="detailSubtitle" :busy="detail.loading || actionBusy" @close="closeDetail">
			<EdgeLoadingState v-if="detail.loading" message="Loading action details..." :skeleton="true" />
			<div v-else-if="detail.payload" class="frontdesk-detail"><EdgeStatusBadge :label="detail.payload.status || 'Open'" :status="detail.payload.status || 'Open'" /><dl><template v-for="entry in detailEntries" :key="entry.label"><dt>{{ entry.label }}</dt><dd>{{ formatValue(entry.value, entry.type) }}</dd></template></dl><div class="frontdesk-actions"><button v-for="link in detailLinks" :key="link.label" type="button" class="edge-button edge-button--compact" @click="openLinked(link)">{{ link.label }}</button></div></div>
			<template #footer><button type="button" class="edge-button" :disabled="actionBusy" @click="closeDetail">Close</button><button v-for="action in detail.payload?.actions || []" :key="action.key" type="button" :class="['edge-button', action.danger ? 'edge-button--danger' : action.primary ? 'edge-button--primary' : '']" :disabled="actionBusy" @click="prepareAction(action)">{{ action.label }}</button></template>
		</EdgeModal>

		<EdgeModal :open="actionDialog.open" :title="actionDialog.title" :subtitle="actionDialog.subtitle" :busy="actionBusy" @close="closeActionDialog">
			<div class="frontdesk-action-form">
				<EdgeInput v-if="actionDialog.action?.key === 'reschedule'" v-model="actionDialog.values.new_date" type="date" label="New Date" required />
				<EdgeInput v-if="actionDialog.action?.key === 'reschedule'" v-model="actionDialog.values.new_time" type="time" label="New Time" />
				<EdgeTextarea v-if="actionNeedsNote" v-model="actionNote" :label="actionDialog.action?.key === 'resolve' ? 'Resolution Note' : 'Note'" :rows="4" />
				<p v-if="!actionNeedsInput">Continue with {{ actionDialog.action?.label }}?</p>
			</div>
			<template #footer><button type="button" class="edge-button" :disabled="actionBusy" @click="closeActionDialog">Cancel</button><button type="button" :class="['edge-button', actionDialog.action?.danger ? 'edge-button--danger' : 'edge-button--primary']" :disabled="actionBusy || !actionFormValid" @click="executeAction">{{ actionBusy ? 'Working…' : actionDialog.action?.label }}</button></template>
		</EdgeModal>
	</EdgeAppShell>
</template>

<script>
const API = Object.freeze({ summary: "vetedge.services.front_desk_action_center.get_front_desk_summary", guestList: "vetedge.services.front_desk_action_center.get_guest_requests", guestDetail: "vetedge.services.front_desk_action_center.get_guest_request_detail", guestAction: "vetedge.services.front_desk_action_center.perform_guest_request_action", queue: "vetedge.services.front_desk_action_center.get_appointment_queue_view", queueDetail: "vetedge.services.front_desk_action_center.get_appointment_action_detail", queueAction: "vetedge.services.front_desk_action_center.perform_appointment_queue_action", missedList: "vetedge.services.front_desk_action_center.get_missed_appointments", missedDetail: "vetedge.services.front_desk_action_center.get_missed_appointment_detail", missedAction: "vetedge.services.front_desk_action_center.perform_missed_appointment_action", link: "vetedge.services.front_desk_action_center.get_front_desk_link_options" });
const TABS = Object.freeze([{ value: "queue", label: "Appointment Queue", description: "Today, tomorrow and future workload" }, { value: "guest", label: "Guest Requests", description: "Registration and appointment conversion" }, { value: "missed", label: "Missed Appointments", description: "Contact, reschedule, cancel or resolve" }]);
const PAGE_META = Object.freeze({
	queue: { title: "Appointment Queue", subtitle: "Manage today's appointment flow and upcoming veterinary workload.", route: "/app/vetedge-front-desk-queue" },
	guest: { title: "Guest Booking Requests", subtitle: "Review guest requests and safely convert them into registered veterinary appointments.", route: "/app/vetedge-front-desk-guest-bookings" },
	missed: { title: "Missed Appointments", subtitle: "Follow up, reschedule, cancel or resolve missed veterinary appointments.", route: "/app/vetedge-front-desk-missed-appointments" },
});
const APPOINTMENT_STATUSES = ["Awaiting Registration", "Owner Requested", "Scheduled", "Confirmed", "Checked In", "In Consultation", "Rescheduled"];
const GUEST_STATUSES = ["Registration Requested", "Registration Confirmed", "Converted", "Cancelled"];
const MISSED_STATUSES = ["Open", "Contacted", "Rescheduled", "Cancelled", "Resolved", "Reopened"];
const errorMessage = (error, fallback) => error?.message || error?._server_messages || error?.exc_type || fallback || __("The operation could not be completed.");
const call = (method, args = {}) => frappe.call(method, args).then((response) => response?.message);
const blankDetail = () => ({ open: false, type: "", loading: false, payload: null });
const blankAction = () => ({ open: false, action: null, title: "", subtitle: "", values: {} });
export default {
	name: "VetEdgeFrontDeskActionCenter",
	data() { const params = new URLSearchParams(window.location.search || ""); const tab = TABS.some((item) => item.value === params.get("tab")) ? params.get("tab") : "queue"; return { tab, fixedTab: "", tabOptions: TABS, summary: {}, queue: { today: [], tomorrow: [], future: [] }, guestList: { rows: [], total: 0, start: 0, page_length: 25 }, missedList: { rows: [], total: 0, start: 0, page_length: 25 }, filters: { branch: "", practitioner: "", status: "", resolved: "", search: "" }, loading: true, error: "", actionBusy: false, detail: blankDetail(), actionDialog: blankAction(), openAction: [{ key: "open", label: "Open", primary: true }], queueColumns: [{ key: "appointment_datetime", label: "Date/Time", type: "datetime" }, { key: "appointment_title", label: "Appointment" }, { key: "patient", label: "Patient" }, { key: "practitioner_name", label: "Practitioner" }, { key: "branch", label: "Branch" }, { key: "status", label: "Status", type: "status" }], guestColumns: [{ key: "guest_name", label: "Guest" }, { key: "pet_name", label: "Pet" }, { key: "preferred_branch", label: "Branch" }, { key: "preferred_datetime", label: "Preferred Date/Time", type: "datetime" }, { key: "status", label: "Status", type: "status" }], missedColumns: [{ key: "appointment_datetime", label: "Date/Time", type: "datetime" }, { key: "patient", label: "Patient" }, { key: "practitioner", label: "Practitioner" }, { key: "branch", label: "Branch" }, { key: "status", label: "Status", type: "status" }, { key: "resolution_status", label: "Resolution", type: "status" }] }; },
	computed: {
		identity() { return frappe.boot?.edgesuite_ui_identity?.vetedge || frappe.boot?.vetedge_ui_identity || {}; }, branchName() { return this.filters.branch || frappe.boot?.edgesuite_product_menu?.branch || "All Branches"; }, userName() { const user = frappe.session?.user || ""; const info = frappe.boot?.user_info?.[user] || {}; return info.fullname || info.full_name || user; }, pageTitle() { return this.fixedTab ? (PAGE_META[this.tab]?.title || "Front Desk") : "Front Desk Action Centre"; }, pageSubtitle() { return this.fixedTab ? (PAGE_META[this.tab]?.subtitle || "Manage front desk work.") : "Review booking requests, manage the live appointment queue and resolve missed appointments."; }, activeRoute() { return this.fixedTab ? (PAGE_META[this.tab]?.route || "/app/vetedge-front-desk-action-center") : "/app/vetedge-front-desk-action-center"; }, appointmentStatusOptions() { return APPOINTMENT_STATUSES.map((value) => ({ value, label: value })); }, guestStatusOptions() { return GUEST_STATUSES.map((value) => ({ value, label: value })); }, missedStatusOptions() { return MISSED_STATUSES.map((value) => ({ value, label: value })); }, resolutionOptions() { return [{ value: "0", label: "Open" }, { value: "1", label: "Resolved" }]; }, queueSections() { return [{ key: "today", label: "Today", description: "Appointments scheduled today", rows: this.queue.today || [] }, { key: "tomorrow", label: "Tomorrow", description: "Appointments scheduled tomorrow", rows: this.queue.tomorrow || [] }, { key: "future", label: "Future", description: "Appointments from the day after tomorrow onward", rows: this.queue.future || [] }]; }, guestFirstVisible() { return this.guestList.total ? this.guestList.start + 1 : 0; }, guestLastVisible() { return Math.min(this.guestList.start + (this.guestList.rows || []).length, this.guestList.total || 0); }, guestHasPrevious() { return this.guestList.start > 0; }, guestHasNext() { return this.guestList.start + this.guestList.page_length < this.guestList.total; }, missedFirstVisible() { return this.missedList.total ? this.missedList.start + 1 : 0; }, missedLastVisible() { return Math.min(this.missedList.start + (this.missedList.rows || []).length, this.missedList.total || 0); }, missedHasPrevious() { return this.missedList.start > 0; }, missedHasNext() { return this.missedList.start + this.missedList.page_length < this.missedList.total; }, detailTitle() { if (!this.detail.payload) return "Front Desk Action"; if (this.detail.type === "guest") return this.detail.payload.values?.guest_name || this.detail.payload.name; if (this.detail.type === "queue") return this.detail.payload.values?.appointment_title || this.detail.payload.name; return `Missed Appointment · ${this.detail.payload.name}`; }, detailSubtitle() { const values = this.detail.payload?.values || {}; return [values.patient_label || values.pet_name, values.owner_label || values.guest_phone, values.branch || values.preferred_branch].filter(Boolean).join(" · "); }, detailEntries() { const values = this.detail.payload?.values || {}; const keys = this.detail.type === "guest" ? [["Guest", "guest_name"], ["Email", "guest_email"], ["Phone", "guest_phone"], ["Pet", "pet_name"], ["Species", "species_label"], ["Breed", "breed_label"], ["Branch", "preferred_branch"], ["Preferred Date/Time", "preferred_datetime", "datetime"], ["Reason", "reason_for_visit"]] : this.detail.type === "queue" ? [["Patient", "patient_label"], ["Owner", "owner_label"], ["Date/Time", "appointment_datetime", "datetime"], ["Practitioner", "practitioner_name"], ["Branch", "branch"], ["Type", "appointment_type"], ["Notes", "notes"]] : [["Patient", "patient_label"], ["Owner", "owner_label"], ["Date/Time", "appointment_datetime", "datetime"], ["Branch", "branch"], ["Practitioner", "practitioner"], ["Missed Reason", "missed_reason"], ["Contact Note", "contact_note"], ["Resolution", "resolution_status"], ["Resolution Note", "resolution_note"]]; return keys.map(([label, key, type]) => ({ label, value: values[key], type })).filter((entry) => entry.value !== undefined && entry.value !== null && entry.value !== ""); }, detailLinks() { const values = this.detail.payload?.values || {}; const links = []; if (values.linked_patient) links.push({ label: "Open Patient", doctype: "Veterinary Patient", name: values.linked_patient }); if (values.linked_appointment || values.appointment) links.push({ label: "Open Appointment", doctype: "Veterinary Appointment", name: values.linked_appointment || values.appointment }); if (values.linked_consultation) links.push({ label: "Open Consultation", route: `/app/vetedge-clinical-workspace?consultation=${encodeURIComponent(values.linked_consultation)}` }); return links; }, actionNeedsNote() { return ["mark_contacted", "reschedule", "cancel_appointment", "resolve", "reopen"].includes(this.actionDialog.action?.key); }, actionNeedsInput() { return this.actionDialog.action?.key === "reschedule" || this.actionNeedsNote; }, actionNote: { get() { return this.actionDialog.values.resolution_note ?? this.actionDialog.values.note ?? ""; }, set(value) { if (this.actionDialog.action?.key === "resolve") this.actionDialog.values.resolution_note = value; else this.actionDialog.values.note = value; } }, actionFormValid() { if (this.actionDialog.action?.key === "reschedule") return Boolean(this.actionDialog.values.new_date); return true; }
	},
	mounted() { this.refreshAll(); },
	methods: {
		async refreshAll() { this.loading = true; this.error = ""; try { const [summary, payload] = await Promise.all([call(API.summary, { branch: this.filters.branch || undefined }), this.loadCurrentTab()]); this.summary = summary || {}; return payload; } catch (error) { this.error = errorMessage(error, __("Front Desk work could not be loaded.")); } finally { this.loading = false; } }, async loadCurrentTab() { if (this.tab === "queue") this.queue = await call(API.queue, { branch: this.filters.branch || undefined, practitioner: this.filters.practitioner || undefined, status: this.filters.status || undefined }); else if (this.tab === "guest") this.guestList = await call(API.guestList, { branch: this.filters.branch || undefined, status: this.filters.status || undefined, search: this.filters.search || "", start: this.guestList.start || 0, page_length: 25 }); else this.missedList = await call(API.missedList, { branch: this.filters.branch || undefined, status: this.filters.status || undefined, resolved: this.filters.resolved, search: this.filters.search || "", start: this.missedList.start || 0, page_length: 25 }); }, changeTab(value) { if (this.fixedTab) return; this.tab = value; this.filters = { branch: this.filters.branch || "", practitioner: "", status: "", resolved: "", search: "" }; const url = new URL(window.location.href); url.pathname = "/app/vetedge-front-desk-action-center"; url.search = new URLSearchParams({ tab: value }).toString(); window.history.replaceState({}, "", url); this.refreshAll(); }, setFilter(field, value) { this.filters[field] = value ?? ""; }, applyFilters() { this.guestList.start = 0; this.missedList.start = 0; this.refreshAll(); }, resetFilters() { const branch = ""; this.filters = { branch, practitioner: "", status: "", resolved: "", search: "" }; this.applyFilters(); }, async linkSearch(fieldname, query) { return (await call(API.link, { fieldname, query })) || []; },
		async openQueueDetail(row) { return this.openDetail("queue", row.name, API.queueDetail); }, async openGuestDetail(row) { return this.openDetail("guest", row.name, API.guestDetail); }, async openMissedDetail(row) { return this.openDetail("missed", row.name, API.missedDetail); }, async openDetail(type, name, method) { this.detail = { open: true, type, loading: true, payload: null }; try { this.detail.payload = await call(method, { name }); } catch (error) { this.error = errorMessage(error); this.detail.open = false; } finally { this.detail.loading = false; } }, closeDetail() { if (!this.actionBusy) this.detail = blankDetail(); }, prepareAction(action) { this.actionDialog = { open: true, action, title: action.label, subtitle: this.detailTitle, values: {} }; }, closeActionDialog() { if (!this.actionBusy) this.actionDialog = blankAction(); }, async executeAction() { if (!this.actionFormValid || this.actionBusy) return; this.actionBusy = true; try { const name = this.detail.payload.name; const modified = this.detail.payload.modified; let result; if (this.detail.type === "guest") result = await call(API.guestAction, { name, action: this.actionDialog.action.key, modified }); else if (this.detail.type === "queue") result = await call(API.queueAction, { name, action: this.actionDialog.action.key, modified }); else result = await call(API.missedAction, { name, action: this.actionDialog.action.key, modified, values: this.actionDialog.values }); this.detail.payload = result?.detail || result || this.detail.payload; this.closeActionDialog(); frappe.show_alert({ message: __("Action completed"), indicator: "green" }); await this.refreshAll(); } catch (error) { this.error = errorMessage(error, __("Action could not be completed.")); } finally { this.actionBusy = false; } },
		previousGuestPage() { this.guestList.start = Math.max(0, this.guestList.start - this.guestList.page_length); this.refreshAll(); }, nextGuestPage() { this.guestList.start += this.guestList.page_length; this.refreshAll(); }, previousMissedPage() { this.missedList.start = Math.max(0, this.missedList.start - this.missedList.page_length); this.refreshAll(); }, nextMissedPage() { this.missedList.start += this.missedList.page_length; this.refreshAll(); }, formatValue(value, type) { if (type === "datetime" && value) return frappe.datetime?.str_to_user?.(value) || value; return value ?? "—"; }, openLinked(link) { if (link.route) return window.location.assign(link.route); if (link.name) frappe.set_route("Form", link.doctype, link.name); }, openRoute(route) { if (!route) return; const adapter = (window.EdgeSuiteUI || window.EdgeUI)?.getAdapter?.("navigation:vetedge"); if (adapter?.open?.(route) === true) return; window.location.assign(route); }
	}
};
</script>

<style scoped>
.frontdesk-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.75rem;margin-bottom:1rem}.frontdesk-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.6rem;margin-bottom:1rem}.frontdesk-tab{background:var(--edge-color-surface,#fff);border:1px solid var(--edge-color-border,#dfe6ec);border-radius:var(--edge-radius-md,.75rem);display:grid;gap:.2rem;padding:.8rem;text-align:left}.frontdesk-tab.is-active{background:var(--edge-color-brand-50,#eef7ff);border-color:var(--edge-color-brand-500,#1677c8)}.frontdesk-tab small,.frontdesk-section header p,.frontdesk-notice p{color:var(--edge-color-ink-500,#617589);margin:0}.frontdesk-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(12rem,1fr));gap:.75rem;width:100%}.frontdesk-section,.frontdesk-notice{background:var(--edge-color-surface,#fff);border:1px solid var(--edge-color-border,#dfe6ec);border-radius:var(--edge-radius-lg,1rem);margin-bottom:1rem;padding:1rem}.frontdesk-section header{align-items:center;display:flex;justify-content:space-between;margin-bottom:.75rem}.frontdesk-section h3{margin:0}.frontdesk-actions{display:flex;flex-wrap:wrap;gap:.5rem}.frontdesk-detail{display:grid;gap:1rem}.frontdesk-detail dl{display:grid;grid-template-columns:minmax(8rem,.4fr) 1fr;margin:0}.frontdesk-detail dt,.frontdesk-detail dd{border-bottom:1px solid var(--edge-color-border,#dfe6ec);margin:0;padding:.5rem}.frontdesk-detail dt{color:var(--edge-color-ink-500,#617589)}.frontdesk-action-form{display:grid;gap:1rem}@media(max-width:48rem){.frontdesk-summary,.frontdesk-tabs{grid-template-columns:1fr}.frontdesk-detail dl{grid-template-columns:1fr}.frontdesk-detail dd{padding-top:0}}
</style>
